namespace ArgentSea.Orleans;
internal static class LoggingExtensions {   // internal: not callable by host code; hosts only observe the events
  public enum EventIdentifier { ExpressionTreeCreation = 1, MapperCacheStatus = 4, MapperProcessTrace = 5, CmdExecuted = 8, PersistanceStart = 13, PersistanceStop = 14 }
  // Ids 1,4,5,8 deliberately reuse the numeric ids of the same categories in ArgentSea.LoggingExtensions.EventIdentifier, so a host filter on e.g. CmdExecuted (8) sees core and grain events alike; 13 and 14 extend past the core enum's last value (BatchStep = 12).
  // Ids are per category, not per event: events of one category share the id and are told apart by EventId.Name.
  // Every event is a LoggerMessage.Define delegate compiled once in the static constructor; EventId.Name is the wrapper method name.

  PersistanceLifecycleOnStart(ILogger, string name)   // Debug, id 13: "Grain persistance {name} is initializing."
  PersistanceLifecycleOnStop(ILogger, string name)    // Debug, id 14: "Grain persistance {name} is terminating."
  OrleansDbCacheMiss(ILogger, string grainType)       // Debug, id 4: "No cached delegate for handling orleans database keys was initialized for type {grainType}; this is normal for the first execution."
  OrleansDbCacheHit(ILogger, string grainType)        // Trace, id 4: "The cached delegate for handling orleans database keys was already initialized for type {grainType}."
  OrleansShardCacheMiss(ILogger, string grainType)    // Debug, id 4: "... orleans sharded keys ...; this is normal for the first execution."
  OrleansShardCacheHit(ILogger, string grainType)     // Trace, id 4: "... orleans sharded keys was already initialized ..."
  TraceMapperGrainPersistance(ILogger, string propertyName) // Trace, id 5: "Grain persistance mapper is now processing property {name}."
  CreatedExpressionTreeForDatabaseKey(ILogger, string grainType, Expression codeBlock) // Debug, id 1: "Compiled code to expression tree for grain {grainType} key mapping for database as:\r\n{code}."
  CreatedExpressionTreeForShardKey(ILogger, string grainType, Expression codeBlock)    // Debug, id 1: "... key mapping for shards as: ..."
  CreatedExpressionTreeForActivation(ILogger, string grainType, Expression codeBlock)  // Debug, id 1: "Compiled code to expression tree for grain {grainType} activation, setting the new state's record identifiers from the grain key, as:\r\n{code}."
  //   the three CreatedExpressionTreeFor* wrappers render codeBlock with a debug-view writer only when logger.IsEnabled(LogLevel.Debug), the level their delegates log at.
  TraceDbReadCmdExecuted / TraceDbWriteCmdExecuted / TraceDbClearCmdExecuted(ILogger, string grainType, long milliseconds)
      // Trace, id 8: "Executed {read|write|clear} Db command on grainType {grainType} in {milliseconds} milliseconds."
  TraceShardReadCmdExecuted / TraceShardWriteCmdExecuted / TraceShardClearCmdExecuted(ILogger, short shardId, string grainType, long milliseconds)
      // Trace, id 8: "Executed {read|write|clear} command on shard {shardId} for grainType {grainType} in {milliseconds} milliseconds."
  //   all six timing wrappers check logger.IsEnabled(LogLevel.Trace) before invoking the delegate.
}
